// ── Graph representations compared ────────────────────────────

// Adjacency list — O(V+E) space, good for sparse graphs
class GraphList {
  #adj = new Map();

  addVertex(v) {
    if (!this.#adj.has(v)) this.#adj.set(v, []);
  }

  addEdge(u, v, directed = false) {
    this.#adj.get(u)?.push(v);
    if (!directed) this.#adj.get(v)?.push(u);
  }

  neighbours(v) { return this.#adj.get(v) ?? []; }

  hasEdge(u, v) { return this.neighbours(u).includes(v); } // O(degree(u))

  vertices() { return [...this.#adj.keys()]; }
}

// Adjacency matrix — O(V²) space, O(1) edge check
class GraphMatrix {
  #n;       // number of vertices
  #matrix;  // n×n 2D array
  #index;   // vertex -> index map

  constructor(vertices) {
    this.#n = vertices.length;
    this.#index = new Map(vertices.map((v, i) => [v, i]));
    this.#matrix = Array.from({ length: this.#n }, () => new Array(this.#n).fill(0));
  }

  addEdge(u, v, directed = false) {
    const ui = this.#index.get(u);
    const vi = this.#index.get(v);
    this.#matrix[ui][vi] = 1;
    if (!directed) this.#matrix[vi][ui] = 1;
  }

  hasEdge(u, v) {                         // O(1)
    return this.#matrix[this.#index.get(u)][this.#index.get(v)] === 1;
  }
}

// Demonstrate the difference
const gl = new GraphList();
['A','B','C','D'].forEach(v => gl.addVertex(v));
gl.addEdge('A','B'); gl.addEdge('A','C'); gl.addEdge('B','D');

console.log('Neighbours of A:', gl.neighbours('A')); // ['B','C']
console.log('Has edge A->D:', gl.hasEdge('A','D'));  // false

const gm = new GraphMatrix(['A','B','C','D']);
gm.addEdge('A','B'); gm.addEdge('A','C'); gm.addEdge('B','D');
console.log('Has edge A->B:', gm.hasEdge('A','B')); // true  — O(1)
console.log('Has edge A->D:', gm.hasEdge('A','D')); // false — O(1)

