// ── BFS and DFS with full distance and path tracking ──────────

class Graph {
  #adj = new Map();
  addVertex(v)            { if (!this.#adj.has(v)) this.#adj.set(v, []); }
  addEdge(u, v, dir=false){ this.#adj.get(u)?.push(v); if (!dir) this.#adj.get(v)?.push(u); }
  neighbours(v)           { return this.#adj.get(v) ?? []; }
  vertices()              { return [...this.#adj.keys()]; }
}

// ── BFS: shortest paths and distances ─────────────────────────
function bfs(graph, start) {
  const visited = new Set([start]);
  const dist    = new Map([[start, 0]]);
  const prev    = new Map([[start, null]]); // for path reconstruction
  const queue   = [start];
  let   head    = 0; // pointer trick — avoids O(n) shift on every dequeue

  while (head < queue.length) {
    const u = queue[head++];
    for (const v of graph.neighbours(u)) {
      if (!visited.has(v)) {
        visited.add(v);
        dist.set(v, dist.get(u) + 1);
        prev.set(v, u);
        queue.push(v);
      }
    }
  }
  return { dist, prev };
}

// Reconstruct path from BFS prev map
function getPath(prev, target) {
  const path = [];
  for (let v = target; v !== null; v = prev.get(v)) path.push(v);
  return path.reverse();
}

// ── DFS: recursive with entry/exit timestamps ──────────────────
function dfsAll(graph) {
  const visited  = new Set();
  const enter    = new Map();
  const exit     = new Map();
  let   timer    = 0;

  function dfs(v) {
    visited.add(v);
    enter.set(v, timer++);
    for (const nb of graph.neighbours(v)) {
      if (!visited.has(nb)) dfs(nb);
    }
    exit.set(v, timer++);
  }

  for (const v of graph.vertices()) if (!visited.has(v)) dfs(v);
  return { enter, exit };
}

// ── Demo ────────────────────────────────────────────────────────
const g = new Graph();
['A','B','C','D','E','F'].forEach(v => g.addVertex(v));
g.addEdge('A','B'); g.addEdge('A','C');
g.addEdge('B','D'); g.addEdge('C','D'); g.addEdge('C','E');
g.addEdge('D','F'); g.addEdge('E','F');

const { dist, prev } = bfs(g, 'A');
console.log('Distance A->F:', dist.get('F')); // 3
console.log('Shortest path A->F:', getPath(prev, 'F').join(' -> ')); // A -> C -> D -> F (or A -> B -> D -> F)

const { enter, exit } = dfsAll(g);
console.log('DFS entry/exit times:', Object.fromEntries(enter));

// ── Cycle detection + Topological sort ────────────────────────

// Three-colour DFS cycle detection for directed graphs
function hasCycleDirected(adj, vertices) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = new Map(vertices.map(v => [v, WHITE]));

  function dfs(v) {
    color.set(v, GRAY);
    for (const nb of (adj[v] ?? [])) {
      if (color.get(nb) === GRAY) return true;   // back edge = cycle
      if (color.get(nb) === WHITE && dfs(nb)) return true;
    }
    color.set(v, BLACK);
    return false;
  }

  return vertices.some(v => color.get(v) === WHITE && dfs(v));
}

// Kahn's algorithm: topological sort + cycle detection
function topoSort(adj, vertices) {
  const inDegree = new Map(vertices.map(v => [v, 0]));

  for (const v of vertices)
    for (const nb of (adj[v] ?? []))
      inDegree.set(nb, (inDegree.get(nb) ?? 0) + 1);

  const queue  = vertices.filter(v => inDegree.get(v) === 0);
  const result = [];
  let   head   = 0;

  while (head < queue.length) {
    const v = queue[head++];
    result.push(v);
    for (const nb of (adj[v] ?? [])) {
      inDegree.set(nb, inDegree.get(nb) - 1);
      if (inDegree.get(nb) === 0) queue.push(nb);
    }
  }

  if (result.length < vertices.length) {
    const cycleNodes = vertices.filter(v => inDegree.get(v) > 0);
    return { order: null, cycle: cycleNodes };
  }
  return { order: result, cycle: null };
}

// ── Demo: course prerequisites ─────────────────────────────────
// Edges: A->C means 'A must come before C'
const dag = {
  'Algebra':    ['Calculus', 'Stats'],
  'Calculus':   ['ML'],
  'Stats':      ['ML', 'DataViz'],
  'ML':         ['DeepLearning'],
  'DataViz':    [],
  'DeepLearning': []
};
const courses = Object.keys(dag);

const { order } = topoSort(dag, courses);
console.log('Study order:', order.join(' -> '));
// Algebra -> Calculus -> Stats -> ML -> DataViz -> DeepLearning (one valid order)

// Cycle detection demo
const cyclic = { A: ['B'], B: ['C'], C: ['A'] }; // A->B->C->A
console.log('Has cycle:', hasCycleDirected(cyclic, ['A','B','C'])); // true

const { order: o2, cycle } = topoSort(cyclic, ['A','B','C']);
console.log('Kahn cycle detected:', cycle); // ['A','B','C']
